class Order
  def initialize(subtotal)
    @subtotal = subtotal
  end

  def total
    @subtotal
  end

  def total_with_coupon(coupon)
    case coupon[:type]
    when :percentage
      @subtotal * (1 - coupon[:value] / 100.0)
    when :fixed
      if coupon[:min_order] && @subtotal < coupon[:min_order]
        @subtotal
      else
        @subtotal - coupon[:value]
      end
    else
      @subtotal
    end
  end
end
